lessons.content:
input[type="text"] {
  border: 1px solid #000;
}
a[href^="https"] {
  color: green;
}

h1, h2, h3 {
  font-family: Arial, sans-serif;
}
.button, .btn-primary {
  padding: 10px;
}

div p {
  color: blue; /* descendant */
}
div > p {
  color: red; /* direct child */
}

li:nth-of-type(2) {
  color: orange;
}
li:nth-last-child(1) {
  font-weight: bold;
}
